// Package schema 持有 Go 工具链（sqlc）编译时读的三份 PostgreSQL 快照。
//
// 本包没有一行运行时代码：这里只有 T6-03 的漂移闸。判据全部是「读文件文本 + 对撞两个
// 不同源的真值」，不需要 PostgreSQL、不需要 pg_dump、不需要 sqlc，所以它在 CI 的 go 作业
// （那个作业没有 pg 服务）里也真跑得动——这一点很重要：本票要拍的坏法是「有人手改了
// go-core/db/schema 的那份 DDL」，而手改之后库里当然没有对应变化，只有仓库里的文本会变。
//
// 六道闸各对着一句谎：
//
//	① 「这份快照是手写/来路不明的」——每份文件头必须有 DO NOT EDIT、source、command、
//	   captured 与一条**真实存在**的 alembic revision（ revision 不存在＝表头是编的）。
//	② 「文件头写着导这几张表，其实文件里是另一些表」——表头 `-t` 白名单必须逐字等于
//	   文件里真的 CREATE 出来的那些表（漏一张＝Go 编译期看不见那张表）。
//	③ 「users 在 Go 侧有两个家」——三份快照的表集合必须两两不重叠，且 users 只在 0001
//	   出现一次（Baseline §22 风险 1/3 的字面落点；本票之前它是「alembic 建 + 0001 再声明」）。
//	④ 「改一点列宽没人看得见」——DDL 主体的 sha256 必须等于 body.sha256 里那一行。
//	   这是工单 §怎么做.4 那句「生成物与仓库文件逐字节比对」：哈希覆盖列名、列宽、可空性、
//	   索引与那条 FK，任何一格的键入改动都先在这里红，而不必等谁去跑一次 pg_dump。
//	⑤ 「快照落后于 alembic 了」——canonical 那两份的表名集合必须逐字等于迁移件里
//	   _TABLES 声明的那些表（另一侧是 Python 侧的真源，不是本目录的复读）。
//	⑥ 「导出器的白名单与仓库内容各说各话」——export_pg_schema.py 里那份 legacy 名单
//	   必须等于 0001 真的导出的那些表。
//
// ④ 与 ⑤ 一起才叫「单一事实源」：④ 保证仓库里的快照没被人动过，⑤ 保证它跟着 alembic 走。
// 只有 ④ 的话，把过期的快照重新生成一遍照样绿；只有 ⑤ 的话，列宽漂移看不见。
//
// 列级（列名/类型/可空/索引）的对账不在这里做第二遍：那条真值链在
// backend/tests/test_canonical_schema.py（alembic DDL ↔ ORM ↔ 实库逐列）与
// backend/tests/test_pg_schema_snapshot.py（alembic ↔ 快照逐字）。本包只拍 Go 看得见的面。
package schema

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"testing"
)

const (
	legacyFile    = "0001_legacy_auth.sql"
	canonicalFile = "0002_canonical_runtime.sql"
	outboxFile    = "0003_outbox_messages.sql"
	checksumFile  = "body.sha256"

	doNotEdit    = "-- DO NOT EDIT: generated by scripts/export_pg_schema.py from the alembic chain (T6-03)."
	bodyMarker   = "--\n-- PostgreSQL database dump"
	exporterPath = "../../../scripts/export_pg_schema.py"
	alembicDir   = "../../../backend/alembic/versions"

	n2Migration    = "c8a2e4b6d0f2_add_canonical_runtime_tables.py"
	n7Migration    = "d9b1f3a5c7e9_add_outbox_messages.py"
	n2TableCount   = 21
	n7TableCount   = 1
	legacyOwnTable = "public.users"
)

var (
	createTableRe  = regexp.MustCompile(`(?m)^CREATE TABLE public\.([a-z_]+) \($`)
	dumpTableArgRe = regexp.MustCompile(`-t (public\.[a-z_]+)`)
	revisionRe     = regexp.MustCompile(`alembic head revision ([0-9a-f]{12})`)
	// alembic 迁移件里的 _TABLES 项：`(\n "name",\n """`。
	tablesEntryRe = regexp.MustCompile(`\(\s*"([a-z_]+)",\s*"""`)
	// 导出器里的 legacy 名单：LEGACY_TABLES = ("public.users", "public.refresh_tokens")
	legacyTupleRe = regexp.MustCompile(`(?s)LEGACY_TABLES = \((.*?)\)`)
)

func read(t *testing.T, name string) string {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join(".", name))
	if err != nil {
		t.Fatalf("读 %s 失败：%v", name, err)
	}
	return string(raw)
}

// snapshotTables 返回文件真的 CREATE 出来的表名（pg_dump 按这个名字序出主体，仍显式排序）。
func snapshotTables(t *testing.T, name string) []string {
	t.Helper()
	var out []string
	for _, m := range createTableRe.FindAllStringSubmatch(read(t, name), -1) {
		out = append(out, "public."+m[1])
	}
	sort.Strings(out)
	return out
}

// ddlBody 取 DDL 主体：从 dump 标记到文件末尾。④ 的哈希与导出器算法覆盖同一段字节，
// 两侧各自实现一次这条切法（Go 与 Python），所以对不上时立刻红，而不是各算各的一半。
func ddlBody(t *testing.T, name string) string {
	t.Helper()
	text := read(t, name)
	at := strings.Index(text, bodyMarker)
	if at < 0 {
		t.Fatalf("%s 里没有 PostgreSQL dump 标记，主体无从切起（这不是快照的形状）", name)
	}
	return text[at:]
}

func sha256Of(s string) string {
	sum := sha256.Sum256([]byte(s))
	return hex.EncodeToString(sum[:])
}

func alembicTables(t *testing.T, migration string) []string {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join(alembicDir, migration))
	if err != nil {
		t.Fatalf("读 alembic 件 %s 失败：%v", migration, err)
	}
	text := string(raw)
	at := strings.Index(text, "_TABLES")
	if at < 0 {
		t.Fatalf("%s 里没有 _TABLES，导出器取不到表清单", migration)
	}
	var out []string
	for _, m := range tablesEntryRe.FindAllStringSubmatch(text[at:], -1) {
		out = append(out, "public."+m[1])
	}
	sort.Strings(out)
	return out
}

// ① 文件头：来路必须是「脚本 + 一条真实存在的 alembic revision」。
func TestEverySnapshotDeclaresItsProvenance(t *testing.T) {
	for _, name := range []string{legacyFile, canonicalFile, outboxFile} {
		text := read(t, name)
		header, _, found := strings.Cut(text, bodyMarker)
		if !found {
			t.Fatalf("%s：没有 dump 标记，表头与主体分不开", name)
		}
		for _, want := range []string{
			doNotEdit,
			"--   source: ",
			"--   command: ",
			"--   captured: 20",
			"-- Regenerate with scripts/export_pg_schema.py; do not hand-edit.",
		} {
			if !strings.Contains(header, want) {
				t.Errorf("%s 的表头缺 %q：这份快照必须能指回一次可复现的导出", name, want)
			}
		}
		rev := revisionRe.FindStringSubmatch(header)
		if rev == nil {
			t.Fatalf("%s 的表头没有 `alembic head revision <12 hex>`：provenance 是编不出来的那一种", name)
		}
		if !hasRevisionFileSuffix(t, rev[1]) {
			t.Errorf("%s 表头记的 alembic revision %s 在仓库里不存在：这份快照不是从本链导出的", name, rev[1])
		}
	}
}

func hasRevisionFileSuffix(t *testing.T, revision string) bool {
	t.Helper()
	entries, err := os.ReadDir(alembicDir)
	if err != nil {
		t.Fatalf("列 %s 失败：%v", alembicDir, err)
	}
	for _, e := range entries {
		if strings.HasPrefix(e.Name(), revision+"_") {
			return true
		}
	}
	return false
}

// ② 表头白名单 == 文件内容。
func TestSnapshotWhitelistMatchesWhatTheFileCreates(t *testing.T) {
	for _, name := range []string{legacyFile, canonicalFile, outboxFile} {
		header, _, _ := strings.Cut(read(t, name), bodyMarker)
		line := ""
		for _, h := range strings.Split(header, "\n") {
			if strings.HasPrefix(h, "--   command: ") {
				line = h
			}
		}
		if line == "" {
			t.Fatalf("%s：找不到 command 行", name)
		}
		var declared []string
		for _, m := range dumpTableArgRe.FindAllStringSubmatch(line, -1) {
			declared = append(declared, m[1])
		}
		sort.Strings(declared)
		got := snapshotTables(t, name)
		if strings.Join(declared, ",") != strings.Join(got, ",") {
			t.Errorf("%s：表头声明 %d 张表，文件里实际 %d 张。表头=%v 文件=%v",
				name, len(declared), len(got), declared, got)
		}
	}
}

// ③ 没有任何一张表在 Go 侧被声明两次（users 那一格的字面落点）。
func TestNoTableIsDeclaredByTwoSnapshots(t *testing.T) {
	seen := map[string]string{}
	for _, name := range []string{legacyFile, canonicalFile, outboxFile} {
		for _, table := range snapshotTables(t, name) {
			if other, dup := seen[table]; dup {
				t.Errorf("%s 在 %s 与 %s 各被 CREATE 一次：DDL 属主分裂，两份里必然有一份是错的",
					table, other, name)
			}
			seen[table] = name
		}
	}
	// 正向证人：归零闸不能扫空集。总数与 0001 的归属都是钉死的。
	if len(seen) != n2TableCount+n7TableCount+2 {
		t.Errorf("三份快照合计 %d 张表，应为 %d（canonical %d + outbox %d + legacy 2）",
			len(seen), n2TableCount+n7TableCount+2, n2TableCount, n7TableCount)
	}
	if seen[legacyOwnTable] != legacyFile {
		t.Errorf("%s 的家应该是 %s，实际在 %s：legacy 面与 canonical 面混了",
			legacyOwnTable, legacyFile, seen[legacyOwnTable])
	}
}

// ④ 逐字节：DDL 主体的 sha256 必须等于指纹清单那一行。
func TestSnapshotBodiesMatchTheChecksumManifest(t *testing.T) {
	raw, err := os.ReadFile(checksumFile)
	if err != nil {
		t.Fatalf("读 %s 失败：%v（它由 scripts/export_pg_schema.py 写，缺了就是没重跑生成器）", checksumFile, err)
	}
	want := map[string]string{}
	for _, line := range strings.Split(string(raw), "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "--") {
			continue
		}
		digest, file, found := strings.Cut(line, "  ")
		if !found {
			t.Fatalf("%s 里有一行不是 `<sha256>  <文件名>`：%q", checksumFile, line)
		}
		want[strings.TrimSpace(file)] = strings.TrimSpace(digest)
	}

	files, err := os.ReadDir(".")
	if err != nil {
		t.Fatalf("列目录失败：%v", err)
	}
	var present []string
	for _, e := range files {
		if strings.HasSuffix(e.Name(), ".sql") {
			present = append(present, e.Name())
		}
	}
	sort.Strings(present)
	var listed []string
	for name := range want {
		listed = append(listed, name)
	}
	sort.Strings(listed)
	if strings.Join(present, ",") != strings.Join(listed, ",") {
		t.Fatalf("%s 覆盖的文件与实际文件不一致：清单=%v 目录=%v", checksumFile, listed, present)
	}
	for _, name := range present {
		got := sha256Of(ddlBody(t, name))
		if want[name] != got {
			t.Errorf("%s 的 DDL 主体与 %s 里的指纹不符：期望 %s…，实际 %s…"+
				"（手改快照＝红；正确做法是跑 scripts/export_pg_schema.py 重导）",
				name, checksumFile, want[name][:12], got[:12])
		}
	}
}

// ⑤ 快照的表名集合跟着 alembic 的 _TABLES 走（另一侧真源在 Python 目录）。
func TestCanonicalSnapshotsMatchAlembicTableLists(t *testing.T) {
	cases := []struct {
		file      string
		migration string
		count     int
		why       string
	}{
		{canonicalFile, n2Migration, n2TableCount, "N2 的 21 张 canonical 表"},
		{outboxFile, n7Migration, n7TableCount, "N7 的 outbox_messages"},
	}
	for _, c := range cases {
		fromAlembic := alembicTables(t, c.migration)
		if len(fromAlembic) != c.count {
			t.Fatalf("%s 里 _TABLES 有 %d 张表，闸的期望是 %d 张（先确认迁移件本身没被改坏）",
				c.migration, len(fromAlembic), c.count)
		}
		got := snapshotTables(t, c.file)
		if strings.Join(fromAlembic, ",") != strings.Join(got, ",") {
			t.Errorf("%s（%s）与 %s 不符：alembic 侧=%v 快照侧=%v；"+
				"要么迁移加了表而快照没重导，要么有人手改了快照",
				c.why, c.migration, c.file, fromAlembic, got)
		}
	}
}

// ⑥ 导出器里那份 legacy 名单 == 0001 实际导出的表（名单与内容不许两个真源）。
func TestExporterLegacyWhitelistMatchesLegacySnapshot(t *testing.T) {
	raw, err := os.ReadFile(exporterPath)
	if err != nil {
		t.Fatalf("读 %s 失败：%v", exporterPath, err)
	}
	block := legacyTupleRe.FindStringSubmatch(string(raw))
	if block == nil {
		t.Fatalf("导出器里找不到 LEGACY_TABLES 这个名单：0001 的白名单失去了唯一落点")
	}
	var declared []string
	for _, m := range regexp.MustCompile(`"(public\.[a-z_]+)"`).FindAllStringSubmatch(block[1], -1) {
		declared = append(declared, m[1])
	}
	sort.Strings(declared)
	got := snapshotTables(t, legacyFile)
	if strings.Join(declared, ",") != strings.Join(got, ",") {
		t.Errorf("导出器名单=%v 而 %s 实际=%v：白名单与快照内容各说各话", declared, legacyFile, got)
	}
	fmt.Fprintf(os.Stderr, "T6-03 漂移闸：%s=%d 张、%s=%d 张、%s=%d 张\n",
		legacyFile, len(got), canonicalFile, len(snapshotTables(t, canonicalFile)),
		outboxFile, len(snapshotTables(t, outboxFile)))
}
